    };

    if let Err(e) = r {
        if e.kind() == ::std::io::ErrorKind::BrokenPipe {
            // Exit gracefully in case of a broken pipe (e.g. 'fd ... | head -n 3').
            process::exit(0);
        } else {
            print_error(format!("Could not write to output: {}", e));
            process::exit(ExitCode::GeneralError.into());
        }
    }
}

